export function newState(boat=GENERIC_BOAT){const s=JSON.parse(JSON.stringify(DEFAULTS));s.fixedControls={};s.sailProfiles={};s.boat=structuredClone(boat);s.sailDesigns=defaultSailDesigns(s.boat);s.sailAreas={gennaker:boat.areas.gennaker,spinnaker:boat.areas.spinnaker};if(boat.id!==GENERIC_BOAT.id)s.genoaSize=105;return s;}
export function courseName(twa){const a=Math.abs(twa);return a<30?'Prua al vento':a<48?'Bolina stretta':a<70?'Bolina larga':a<105?'Traverso':a<145?'Lasco':a<170?'Gran lasco':'Poppa';}
const references=new Map();
export function installReference(reference){references.set(reference.key,reference);if(references.size>32)references.delete(references.keys().next().value);}
export function getReference(s){return references.get(referenceKey(s));}
export function evaluate(s,speed=0,quality='normal'){const m=aeroForces(s,speed,quality),polarTarget=polarSpeed(s.windSpeed,s.windAngle,s),reference=getReference(s),provisional=!reference&&polarTarget>.01?provisionalReference(s,polarTarget):null;let targetSpeed=0,efficiency=0;if(polarTarget>.01){if(reference&&reference.score>.01){targetSpeed=polarTarget*Math.pow(clamp(m.usefulDrive/reference.score,0,3),1/3);efficiency=100*m.usefulDrive/reference.score;}else{/* Original inventory at original dimensions, never today's active sail area. */const baseline=Math.max(1,provisional?.score||1);targetSpeed=polarTarget*Math.cbrt(clamp(m.usefulDrive/baseline,0,3));efficiency=100*m.usefulDrive/baseline;}}const settlingTime=clamp(boatProfile(s).displacement*1.05*Math.max(.5,polarTarget*.514444)/(3*Math.max(100,reference?.score||provisional?.score||m.usefulDrive)),1.2,6.0),vmg=speed*Math.cos((Math.abs(s.windAngle)+m.leeway)*RAD);return{...m,settlingTime,vmg,polarTarget,targetSpeed,polarEfficiency:polarTarget>.01?speed/polarTarget*100:0,efficiency:clamp(efficiency,0,100),referenceReady:!!reference,referenceScore:reference?.score||0,referenceAttachment:reference?.attachment||0,referencePressure:reference?.maxPressure||0,referenceCp95:reference?.cp95||0};}
export function optimize(s){const reference=computeReference(s);installReference(reference);const result=optimizeForReference(s,reference);Object.assign(s,result.state);return s;}
export function equilibrium(input){const s={...input};delete s.jibAngleRad;delete s.jibAngularVelocity;delete s.jibSide;let v=polarSpeed(s.windSpeed,s.windAngle,s)*.8;for(let i=0;i<24;i++)v=lerp(v,evaluate(s,v).targetSpeed,.45);return evaluate(s,v);}
